mapped as (
  select i.code, i.el,
         (select string_agg(coalesce(g.en, t.term), ', ' order by t.ord)
            from unnest(string_to_array(i.el, ', ')) with ordinality as t(term, ord)
            left join ingredient_glossary g on g.el = t.term) as en
    from input i
)
update dishes d
   set desc_el = m.el, desc_en = m.en, updated_at = now()
  from mapped m
 where d.external_id = m.code;

